namespace ProjectA {
    int status_code = 0;
    namespace Utility {
        void log_event(const char* msg);
    }
}

// Explicit access using scope resolution
int err = ProjectA::status_code;

// Accessing nested members
ProjectA::Utility::log_event("Started");

// Global scope resolution
int buffer_size = 1024;
namespace Module {
    int buffer_size = 512;
    int local = buffer_size;   // Module::buffer_size
    int global = ::buffer_size; // Global buffer_size
}

// Using declaration (pulling one symbol)
using ProjectA::status_code;
int current_status = status_code;
